function runQueue(ops) {
    const queue = [];
    const res = [];
    for (let op of ops) {
        if (op.startsWith('push')) {
            queue.push(parseInt(op.split(' ')[1]));
            res.push('null');
        } else if (op === 'pop') {
            res.push((queue.shift() || 'null').toString());
        } else if (op === 'peek') {
            res.push((queue[0] || 'null').toString());
        } else if (op === 'empty') {
            res.push((queue.length === 0).toString());
        }
    }
    return res;
}
